// Loads the Rust/wasm app and connects the HTML buttons to it.
//
// `./pkg/game_of_life.js` is generated by `./wasm_build.sh` (wasm-pack). It exports:
// - `init` (default export): downloads and starts the .wasm file. Starting it automatically
//   runs `run_web` in src/app.rs (marked `#[wasm_bindgen(start)]`).
// - the control functions from src/web_controls.rs, under their JavaScript names.
import init, {
  playPause,
  stepForward,
  randomiseState,
  updateFps,
  resetState,
} from "./pkg/game_of_life.js";

async function run() {
  try {
    console.log("Loading WASM...");
    console.log("WebGPU supported:", !!navigator.gpu);

    await init();
    console.log("WASM Loaded successfully!");
  } catch (error) {
    console.error("Failed to load WASM:", error);
  }

  // The buttons in index.html call e.g. `window.playPause()` from their `onclick`.
  // ES modules don't create globals, so we attach the functions to `window` ourselves.
  window.playPause = playPause;
  window.stepForward = stepForward;
  window.randomiseState = randomiseState;
  window.updateFps = updateFps;
  window.resetState = resetState;
}

run();
